<script lang="ts">
  import { onMount } from 'svelte';
  import { ArrowLeft, BookOpen, ExternalLink, FileText } from '@lucide/svelte';
  import Dropdown, { type DropdownOption } from '$lib/components/ui/Dropdown.svelte';
  import { featureApiJson } from '$lib/client/feature-api.js';
  import { notify } from '$lib/client/notifications.js';
  const { data } = $props() as { data:{slug:string} };
  type Resource={id:string;title:string;description:string|null;resourceType:string;subject:string|null;url:string;doi:string|null;citation:string|null;accessLevel:string;createdAt:string;authorUsername:string|null;authorName:string|null};
  let resources=$state<Resource[]>([]);let loading=$state(true);let error=$state('');let creating=$state(false);let busy=$state(false);
  let title=$state('');let description=$state('');let resourceType=$state('article');let subject=$state('');let url=$state('');let doi=$state('');let citation=$state('');let accessLevel=$state('community');
  const typeOptions:DropdownOption[]=[{value:'article',label:'Article'},{value:'paper',label:'Research paper'},{value:'book',label:'Book'},{value:'video',label:'Lecture / video'},{value:'dataset',label:'Dataset'},{value:'lecture',label:'Lecture notes'},{value:'tool',label:'Tool'},{value:'other',label:'Other'}];
  const accessOptions:DropdownOption[]=[{value:'community',label:'Community members'},{value:'public',label:'Public resource'}];
  async function load(){loading=true;error='';try{const r=await featureApiJson<{resources:Resource[]}>(`/communities/${encodeURIComponent(data.slug)}/resources`);resources=r.resources;}catch(e){error=e instanceof Error?e.message:'Could not load resources.';}finally{loading=false;}}
  async function create(){if(!title.trim()||!url.trim()){error='Add a resource title and URL.';return;}busy=true;error='';try{await featureApiJson(`/communities/${encodeURIComponent(data.slug)}/resources`,{method:'POST',body:JSON.stringify({title,description,resourceType,subject,url,doi,citation,accessLevel})});title='';description='';url='';doi='';citation='';creating=false;notify('Resource added to the library.','success');await load();}catch(e){error=e instanceof Error?e.message:'Could not add resource.';notify(error,'error');}finally{busy=false;}}
  onMount(()=>{void load();});
</script>
<svelte:head><title>Academic library · c/{data.slug} · Nexus</title></svelte:head>
<div class="mx-auto w-full max-w-[1500px] px-3 pb-20 sm:px-6"><a href={`/c/${encodeURIComponent(data.slug)}`} class="inline-flex items-center gap-2 text-xs font-bold text-slate-400 hover:text-white"><ArrowLeft size={15}/> c/{data.slug}</a><header class="mt-4 flex flex-wrap items-end justify-between gap-4 border-b border-white/10 pb-5"><div><div class="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-orange-300"><BookOpen size={16}/> Academic workspace</div><h1 class="mt-2 text-3xl font-black text-white">Resource library</h1><p class="mt-2 text-sm text-slate-400">Share papers, references, lecture notes, datasets, and tools. Cite sources clearly.</p></div><button onclick={()=>creating=!creating} class="rounded-full bg-orange-400 px-4 py-2.5 text-sm font-extrabold text-slate-950">{creating?'Cancel':'＋ Add resource'}</button></header>
{#if creating}<section class="mt-4 rounded-xl border border-white/10 bg-[#101719] p-4"><h2 class="font-extrabold text-white">Add a study resource</h2><div class="mt-4 grid gap-3 sm:grid-cols-2"><label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2">Title<input bind:value={title} maxlength="180" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="A clear, descriptive title"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Resource type<Dropdown label="Resource type" options={typeOptions} value={resourceType} onChange={v=>resourceType=v} fullWidth/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Subject<input bind:value={subject} maxlength="100" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="Computer science, biology…"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2">URL<input bind:value={url} type="url" maxlength="2048" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="https://doi.org/…"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">DOI (optional)<input bind:value={doi} maxlength="160" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="10.1234/example"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300">Visibility<Dropdown label="Resource visibility" options={accessOptions} value={accessLevel} onChange={v=>accessLevel=v} fullWidth/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2">Citation<textarea bind:value={citation} rows="2" maxlength="1000" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="APA, MLA, BibTeX summary…"/></label><label class="grid gap-1.5 text-xs font-bold text-slate-300 sm:col-span-2">Description<textarea bind:value={description} rows="3" maxlength="3000" class="rounded-lg border border-white/10 bg-black/20 p-3 text-sm text-white" placeholder="Why is this useful? What should readers know?"/></label></div>{#if error}<p role="alert" class="mt-3 text-sm text-rose-200">{error}</p>{/if}<div class="mt-4 flex justify-end"><button onclick={create} disabled={busy} class="rounded-full bg-orange-400 px-4 py-2.5 text-sm font-extrabold text-slate-950 disabled:opacity-50">{busy?'Saving…':'Add resource'}</button></div></section>{/if}
{#if error&&!creating}<p role="alert" class="mt-4 rounded-xl border border-rose-300/20 p-3 text-sm text-rose-200">{error}</p>{/if}
{#if loading}<p class="mt-8 text-sm text-slate-400">Loading resource library…</p>{:else if !resources.length}<div class="mt-5 rounded-xl border border-dashed border-white/15 p-10 text-center"><BookOpen size={32} class="mx-auto text-slate-500"/><h2 class="mt-3 font-bold text-white">The library is empty</h2><p class="mt-2 text-sm text-slate-400">Share a source that helped your work or study.</p></div>{:else}<div class="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{#each resources as resource (resource.id)}<article class="rounded-xl border border-white/10 bg-[#101719] p-4"><div class="flex items-center justify-between gap-3"><span class="rounded-full bg-orange-400/10 px-2 py-1 text-[10px] font-extrabold uppercase text-orange-300">{resource.resourceType}</span>{#if resource.subject}<span class="truncate text-[10px] text-slate-500">{resource.subject}</span>{/if}</div><h2 class="mt-3 text-lg font-extrabold leading-snug text-white">{resource.title}</h2>{#if resource.description}<p class="mt-2 line-clamp-3 text-sm leading-6 text-slate-400">{resource.description}</p>{/if}{#if resource.doi}<p class="mt-3 break-all text-[11px] text-slate-500">DOI: {resource.doi}</p>{/if}{#if resource.citation}<details class="mt-3"><summary class="cursor-pointer text-xs font-bold text-slate-300">View citation</summary><p class="mt-2 whitespace-pre-wrap text-xs leading-5 text-slate-400">{resource.citation}</p></details>{/if}<a class="mt-4 inline-flex items-center gap-2 text-xs font-extrabold text-orange-300 hover:text-orange-200" href={resource.url} target="_blank" rel="noopener noreferrer nofollow"><FileText size={14}/> Open source <ExternalLink size={12}/></a><p class="mt-3 text-[10px] text-slate-600">Added by u/{resource.authorUsername||resource.authorName||'member'}</p></article>{/each}</div>{/if}</div>
